const errorData = $json.execution?.error || {};
const workflow = $json.workflow?.name || 'Unknown Workflow';

console.error(`[CRITICAL] LendLoop Workflow Failure in '${workflow}':`, {
  message: errorData.message,
  node: errorData.node?.name,
  timestamp: new Date().toISOString()
});

return {
  json: {
    alert: 'Workflow Failure Logged',
    workflow,
    errorMessage: errorData.message,
    failedNode: errorData.node?.name,
    executionId: $json.execution?.id
  }
};
